# Not in the book: the newest upstream release, built with cargo as its
# release workflow does (default features: battery and notify). Upstream
# publishes checksums only for its binary archives, none for the source
# archive.
build() {
    # Keep cargo's registry and download cache inside the build directory
    # rather than in root's home in the shared build root.
    export CARGO_HOME="$PWD/.cargo-home"
    # --locked: build exactly the crate versions in upstream's Cargo.lock.
    cargo build --release --locked

    # Shell completions, generated by starship itself. Upstream has no
    # manual page.
    local starship=target/release/starship shell
    for shell in bash zsh fish; do
        "$starship" completions "$shell" > "starship.$shell"
    done
}

package() {
    install -Dm755 target/release/starship "$DESTDIR/usr/bin/starship"
    install -Dm644 starship.bash "$DESTDIR/usr/share/bash-completion/completions/starship"
    install -Dm644 starship.zsh "$DESTDIR/usr/share/zsh/site-functions/_starship"
    install -Dm644 starship.fish "$DESTDIR/usr/share/fish/vendor_completions.d/starship.fish"
}
